class Solution {
    func encode(_ strs: [String]) -> String {
        if strs.isEmpty { return "" }

        var sizes: [String] = []
        for s in strs {
            sizes.append(String(s.count))
        }
        return sizes.joined(separator: ",") + ",#" + strs.joined()
    }

    func decode(_ s: String) -> [String] {
        if s.isEmpty { return [] }
        let sArr = Array(s)
        var sizes: [Int] = []
        var res: [String] = []
        var i = 0

        while sArr[i] != "#" {
            let start = i
            while sArr[i] != "," {
                i += 1
            }
            sizes.append(Int(String(sArr[start..<i]))!)
            i += 1
        }

        i += 1
        for sz in sizes {
            let substring = String(sArr[i..<i+sz])
            res.append(substring)
            i += sz
        }
        return res
    }
}
